const ZAD_TOKENS_CSS=`\n/* ═══════════════ زاد — Design Tokens v1.0 ═══════════════ */\n\n:root {\n  /* ── الألوان الأساسية ──────────────────────────────────────\n     مستعارة الآن من primitives موحّدة في css/style.css (وليست\n     قيماً خاماً مكررة هنا) — القيم نفسها لم تتغيّر، فقط أصبح لها\n     مصدر واحد بدل تعريفين مستقلّين كانا بإمكانهما الانجراف عن\n     بعضهما بمرور الوقت (وهذا بالضبط ما حدث قبل هذا الإصلاح). تبقى\n     ثابتة عبر كل الثيمات عمداً — تُستخدَم كخلفيات صلبة مع نص أبيض\n     في عدة أماكن (أزرار/badges)، فلو صارت متغيّرة مع الثيم لانكسر\n     تباين النص الأبيض فوقها. أي استخدام كنص مباشر على خلفية تتغيّر\n     لونها يجب أن يستخدم توكن دلالي متوافق مع الثيم بدل هذه مباشرة\n     (--green-mid/--green-deep/--gold-dark/--sys-*) — كما فُعل بالفعل\n     في كل نقاط الاستهلاك النصي المعروفة. */\n  --zad-green-900: var(--primitive-green-900, #0e3b2e);\n  --zad-green-700: var(--primitive-green-700, #1a5d47);\n  --zad-green-500: var(--primitive-green-500, #2a7a5f);\n  --zad-green-100: var(--primitive-green-100, #e8f4ef);\n\n  --zad-gold-700:  var(--primitive-gold-700, #b87200);\n  --zad-gold-500:  var(--primitive-gold-500, #c9a14a);\n  --zad-gold-100:  var(--primitive-gold-100, #fff8e8);\n\n  /* هذه الثلاثة استُهلكت تاريخياً كنص فقط (لا خلفية) في كل نقاط\n     الاستخدام المعروفة، فتُستعار مباشرة من توكنز دلالية متوافقة مع\n     الثيم أصلاً بدل primitive ثابت — أي استخدام جديد لها سيرث\n     التوافق مع الوضع الداكن/OLED تلقائياً بدل الحاجة لإصلاح لاحق. */\n  --zad-amber:     var(--sys-orange, #ff9500);\n  --zad-coral:     var(--sys-red, #c0392b);\n  --zad-purple:    var(--sys-purple, #4a3580);\n\n  /* ── نسب contrast آمنة (WCAG 2.2 AA) ─────────────── */\n  /* green-900 on white:  contrast 9.4:1  ✅ AAA */\n  /* green-700 on white:  contrast 6.8:1  ✅ AA  */\n  /* gold-500 on dark:    contrast 4.6:1  ✅ AA  */\n\n  /* ── المسافات (8px grid) ───────────────────────────── */\n  --space-1: 4px;\n  --space-2: 8px;\n  --space-3: 12px;\n  --space-4: 16px;\n  --space-5: 24px;\n  --space-6: 32px;\n  --space-7: 48px;\n\n  /* ── نصف القطر ──────────────────────────────────────── */\n  --radius-sm:  8px;\n  --radius-md:  12px;\n  --radius-lg:  16px;\n  --radius-xl:  20px;\n  --radius-full: 9999px;\n\n  /* ── الخطوط ─────────────────────────────────────────── */\n  --font-ui:    'ThmanyahSans', 'Segoe UI', 'Arial', sans-serif;\n  --font-quran: 'ThmanyahSerifText', 'Amiri', 'Traditional Arabic', serif;\n\n  /* ── أحجام الخط ──────────────────────────────────────── */\n  --text-xs:   11px;\n  --text-sm:   13px;\n  --text-base: 15px;\n  --text-md:   16px;\n  --text-lg:   18px;\n  --text-xl:   22px;\n  --text-2xl:  28px;\n  --text-3xl:  36px;\n\n  /* ── التحولات (Calm UX: خفيفة وهادئة) ─────────────── */\n  --transition-fast:   150ms ease;\n  --transition-base:   250ms ease;\n  --transition-slow:   400ms ease;\n  --transition-calm:   350ms cubic-bezier(0.4, 0, 0.2, 1);\n\n  /* ── الظلال ──────────────────────────────────────────── */\n  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);\n  --shadow-md:  0 4px 12px rgba(0,0,0,.10), 0 2px 4px rgba(0,0,0,.06);\n  --shadow-lg:  0 10px 30px rgba(0,0,0,.15), 0 4px 8px rgba(0,0,0,.08);\n\n  /* ── مؤشر التركيز (Accessibility) ───────────────────── */\n  --focus-ring: 0 0 0 3px rgba(14,59,46,.4);\n  --focus-ring-gold: 0 0 0 3px rgba(201,161,74,.5);\n}\n\n/* ── 2. Reduced Motion — احترام تفضيلات المستخدم ─────────────────────────── */\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after {\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important;\n    scroll-behavior: auto !important;\n  }\n\n  /* إيقاف الأنيميشن في GSAP يدوياً في JS */\n}\n\n/* ── 3. مؤشرات التركيز (WCAG 2.2 — Focus Visible) ────────────────────────── */\n:focus-visible {\n  outline: 3px solid var(--zad-green-700);\n  outline-offset: 2px;\n  border-radius: var(--radius-sm);\n}\n\n/* إزالة outline الافتراضي القبيح مع الحفاظ على الوصول */\n:focus:not(:focus-visible) {\n  outline: none;\n}\n\n/* ── 4. Buttons — حجم لمسي مناسب (44x44px minimum WCAG) ──────────────────── */\nbutton, .btn, [role="button"], .check, .fast-day, .charity-act {\n  min-height: 44px;\n  min-width: 44px;\n}\n\n/* ── 5. التباين — نصوص قابلة للقراءة لكبار السن ───────────────────────────── */\n.muted, small, .tag, .prayer-sub, .adhkar-source {\n  color: #5a5a58; /* contrast 5.8:1 على أبيض ✅ */\n}\n\n/* ── 6. الخط العربي — القرآن الكريم بالرسم العثماني ──────────────────────── */\n.quran-text, .adhkar-arabic, .af-ms-dua, [lang="ar-Quran"] {\n  font-family: var(--font-quran);\n  font-size: var(--qf-size, 24px);\n  line-height: 2.2;\n  letter-spacing: 0;\n  direction: rtl;\n  text-align: center;\n}\n\n/* ── 7. RTL Consistency ──────────────────────────────────────────────────── */\nhtml {\n  direction: rtl;\n}\n[dir="ltr"], .ltr {\n  direction: ltr;\n  text-align: left;\n}\n\n/* ── 8. Calm UX — تقليل مصادر التشتت ──────────────────────────────────────── */\n\n/* لا animations أثناء القراءة (في وضع المصحف) */\n.mushaf-mode * {\n  animation: none !important;\n  transition: none !important;\n}\n\n/* الإشعارات تظهر بهدوء */\n.toast {\n  transition: opacity var(--transition-slow), transform var(--transition-slow);\n}\n\n/* الكاردات تظهر بتأخير بسيط للتسلسل الطبيعي */\n.card.reveal {\n  opacity: 0;\n  transform: translateY(8px);\n  transition: opacity var(--transition-slow), transform var(--transition-slow);\n}\n.card.reveal.visible {\n  opacity: 1;\n  transform: translateY(0);\n}\n\n/* ── 9. High Contrast Mode ───────────────────────────────────────────────── */\n@media (prefers-contrast: high) {\n  :root {\n    --zad-green-900: #000;\n    --zad-gold-500: #7a5000;\n  }\n  .card { border: 2px solid #000; }\n}\n\n/* ── 10. Print — إزالة عناصر غير ضرورية ────────────────────────────────── */\n@media print {\n  .sidebar, .topbar, .pwa-banner, .toast, .scroll-top-btn, \n  .btn, footer, nav { display: none !important; }\n  .main { margin: 0 !important; padding: 0 !important; }\n}\n`;function injectDesignTokens(){if(document.getElementById("zad-design-tokens"))return;const style=document.createElement("style");style.id="zad-design-tokens";style.textContent=ZAD_TOKENS_CSS;document.head.insertBefore(style,document.head.firstChild)}function enhanceAccessibility(){const EMOJI_LABELS={"🌙":"تفعيل الوضع الداكن","☀️":"تفعيل الوضع الفاتح","⚫":"وضع OLED","🔔":"الإشعارات","🔕":"إيقاف الإشعارات","↑":"العودة لأعلى","☰":"القائمة","🔍":"بحث","❌":"إغلاق","✅":"مكتمل","🏠":"الرئيسية"};document.querySelectorAll('button, [role="button"]').forEach(btn=>{if(btn.getAttribute("aria-label"))return;const text=btn.textContent.trim();if(EMOJI_LABELS[text]){btn.setAttribute("aria-label",EMOJI_LABELS[text])}else if(text.length<=2&&/[\u{1F000}-\u{1FFFF}]/u.test(text)){btn.setAttribute("aria-describedby",btn.id||"btn-"+Math.random().toString(36).slice(2,6))}});if(!document.getElementById("skip-to-main")){const skip=document.createElement("a");skip.id="skip-to-main";skip.href="#main-content";skip.textContent="انتقل للمحتوى الرئيسي";skip.style.cssText=`\n      position: absolute;\n      top: -40px;\n      right: 16px;\n      background: var(--zad-green-900, #0e3b2e);\n      color: #fff;\n      padding: 8px 16px;\n      border-radius: 0 0 8px 8px;\n      font-size: 14px;\n      font-weight: 700;\n      z-index: 10000;\n      transition: top 0.2s;\n      text-decoration: none;\n    `;skip.addEventListener("focus",()=>{skip.style.top="0"});skip.addEventListener("blur",()=>{skip.style.top="-40px"});document.body.insertBefore(skip,document.body.firstChild);const main=document.querySelector(".main");if(main&&!main.id)main.id="main-content"}const sidebar=document.querySelector(".sidebar");if(sidebar&&!sidebar.getAttribute("role")){sidebar.setAttribute("role","navigation");sidebar.setAttribute("aria-label","القائمة الرئيسية")}const main=document.querySelector(".main");if(main&&!main.getAttribute("role")){main.setAttribute("role","main")}document.querySelectorAll(".check[data-key]").forEach(el=>{if(!el.getAttribute("tabindex"))el.setAttribute("tabindex","0");if(!el.getAttribute("role"))el.setAttribute("role","checkbox");const key=el.dataset.key;const labels={fajr:"صلاة الفجر",zuhr:"صلاة الظهر",asr:"صلاة العصر",maghrib:"صلاة المغرب",isha:"صلاة العشاء",qiyam:"قيام الليل",morning_dhikr:"أذكار الصباح",evening_dhikr:"أذكار المساء",takbeer_100:"التكبير",tawbah:"التوبة والاستغفار",rawatib:"السنن الرواتب",duha:"صلاة الضحى"};if(labels[key]&&!el.getAttribute("aria-label")){el.setAttribute("aria-label",labels[key])}const isDone=el.classList.contains("done");el.setAttribute("aria-checked",isDone?"true":"false");const observer=new MutationObserver(()=>{el.setAttribute("aria-checked",el.classList.contains("done")?"true":"false")});observer.observe(el,{attributes:true,attributeFilter:["class"]});if(!el._a11yBound){el._a11yBound=true;el.addEventListener("keydown",e=>{if(e.key===" "||e.key==="Enter"){e.preventDefault();el.click()}})}});document.querySelectorAll("img:not([alt])").forEach(img=>{img.setAttribute("alt","")});if(!document.documentElement.getAttribute("lang")){document.documentElement.setAttribute("lang","ar")}}function applyCalmUX(){const prefersReduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(prefersReduced){if(window.gsap){gsap.globalTimeline.pause();gsap.defaults({duration:0})}document.documentElement.style.setProperty("--transition-fast","0ms");document.documentElement.style.setProperty("--transition-base","0ms");document.documentElement.style.setProperty("--transition-slow","0ms");document.documentElement.style.setProperty("--transition-calm","0ms")}const quietPages=["mushaf","arafah","adhkar","ai"];const currentPage=window.location.pathname.split("/").pop().split(".")[0];if(quietPages.includes(currentPage)){window._calmMode=true;window.triggerConfetti=function(){if(typeof showToast==="function"){showToast("🎉 ما شاء الله — تقبّل الله منك")}}}const _origSchedule=window.scheduleReminders;if(_origSchedule){window.scheduleReminders=function(){const hour=(new Date).getHours();if(hour>=0&&hour<5){console.log("[CalmUX] الإشعارات مؤجلة — وقت الراحة");return}_origSchedule()}}}function ensureArabicRendering(){if(document.fonts?.ready){document.fonts.ready.then(()=>{const fontsLoaded=[...document.fonts.values()].filter(f=>f.status==="loaded");console.log(`[Arabic] ${fontsLoaded.length} خط محمّل`)})}document.querySelectorAll(".main, .sidebar, .card, section").forEach(el=>{if(!el.hasAttribute("dir")&&!el.closest("[dir]")){el.setAttribute("dir","rtl")}});document.querySelectorAll("[data-arabic-num]").forEach(el=>{const num=parseFloat(el.textContent);if(!isNaN(num)){el.textContent=num.toLocaleString("ar-EG")}})}function checkContrastIssues(){if(!window._zadDevMode)return;const issues=[];document.querySelectorAll("p, span, div, h1, h2, h3, h4, button").forEach(el=>{const style=window.getComputedStyle(el);const fg=style.color;const bg=style.backgroundColor;if(fg===bg){issues.push({el:el,issue:"نص ملون نفس خلفيته"})}});if(issues.length>0){console.warn("[A11y] مشاكل contrast محتملة:",issues.length);issues.forEach(({el:el,issue:issue})=>console.warn(issue,el))}}document.addEventListener("DOMContentLoaded",()=>{injectDesignTokens();enhanceAccessibility();applyCalmUX();ensureArabicRendering();const observer=new MutationObserver(()=>{clearTimeout(window._a11yTimer);window._a11yTimer=setTimeout(()=>{enhanceAccessibility()},500)});observer.observe(document.body,{childList:true,subtree:true});console.log("[ZadDesign] ✅ Design System + A11y + Calm UX جاهزة")});